const pending = new Map<DiagramType, Promise<boolean>>();

// Loads and registers one diagram type. Resolves to false for a type Pele does not draw.
export function load(type: DiagramType | null): Promise<boolean> {
  if (type === null) return Promise.resolve(false);
  if (registered(type)) return Promise.resolve(true);
  let promise = pending.get(type);
  if (promise === undefined) {
    const loader = loaders.get(type);
    if (loader === undefined) return Promise.resolve(false);
    promise = loader().then(
      (diagram) => {
        register(diagram);
        return true;
      },
      (error) => {
        pending.delete(type);
        throw error;
      }
    );
    pending.set(type, promise);
  }
  return promise;
}

// Loads the diagram type that the text needs, then renders it.
export async function renderAsync(text: string, options: RenderOptions = {}): Promise<RenderResult> {
  let type: DiagramType | null = null;
  try {
    type = detectType(text);
  } catch {
    // render() reports what is wrong with the text.
  }
  await load(type);
  return render(text, options);
}

// Loads the diagram type that the text needs, then mounts it. A later update() to another
// type needs that type loaded first.
export async function mountAsync(element: HTMLElement, text: string, options: MountOptions = {}): Promise<Mounted> {
  let type: DiagramType | null = null;
  try {
    type = detectType(text);
  } catch {
    // mount() reports what is wrong with the text.
  }
  await load(type);
  return mount(element, text, options);
}

